-- Seed banyak merchant + menu (foto = /assets/img/menu/<slug>.webp). Idempoten.
begin;
select setval(pg_get_serial_sequence('public.users','id'), (select max(id) from public.users));
select setval(pg_get_serial_sequence('public.merchants','id'), (select max(id) from public.merchants));
select setval(pg_get_serial_sequence('public.menus','id'), (select max(id) from public.menus));

-- Normalisasi menu lama (id 1–4): samakan nama dengan foto yang tersedia
update public.menus set image = '/assets/img/menu/nasi-goreng.webp' where id = 1;
update public.menus set name = 'Sate Kambing (10 tusuk)', description = 'Sate kambing muda', image = '/assets/img/menu/sate-kambing.webp' where id = 2;
update public.menus set image = '/assets/img/menu/es-teh-manis.webp' where id = 3;
update public.menus set name = 'Lontong Sayur', description = 'Lontong dengan sayur santan', image = '/assets/img/menu/lontong.webp' where id = 4;

commit;